from typing import List, Tuple, Dict

def shoot(rounds: List[Tuple[Dict[str, str], bool]]) -> str:
    pete_score = 0
    phil_score = 0

    for round in rounds:
        result, multiplier = round
        pete_hits = result['P1'].count('X')
        phil_hits = result['P2'].count('X')

        if multiplier:
            pete_score += pete_hits * 2
            phil_score += phil_hits * 2
        else:
            pete_score += pete_hits * 1
            phil_score += phil_hits * 1

    if pete_score > phil_score:
        return 'Pete Wins!'
    elif phil_score > pete_score:
        return 'Phil Wins!'
    else:
        return 'Draw!'
